-- Bounded ordinary cross-workflow acceptance. Disposable local PostgreSQL only.
-- Uses the existing notifications fixture plus reviewed accumulated baseline DDL.
-- No hosted target, adversarial checks, direct balance writes or ledger rewrites.
begin;
create function pg_temp.daily_assert(ok boolean, label text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'DAILY ACCEPTANCE FAILED: %',label; end if; end $$;
set local role authenticated;
set local request.jwt.claim.sub='66000000-0000-0000-0000-000000000001';
do $$
declare
 org uuid:='6aaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa'; business_day date:=(now() at time zone 'America/Toronto')::date;
 a uuid:='d1111111-1111-4111-8111-111111111111'; b uuid:='d2222222-2222-4222-8222-222222222222';
 job uuid:=gen_random_uuid(); stockjob uuid:=gen_random_uuid(); supplierjob uuid:=gen_random_uuid();
 p uuid; p2 uuid; lot uuid; lot2 uuid; unsafe uuid; tr uuid; canceltr uuid; cnt uuid; po uuid; pol uuid; receipt uuid;
 customer uuid; sale uuid; sale2 uuid; refund uuid; item uuid; result jsonb; payload jsonb; lines jsonb; quote jsonb; before_n bigint; dest_lot uuid;
begin
 perform public.create_branch_with_access(a,org,'Daily A',null,'Montréal',null);
 perform public.create_branch_with_access(b,org,'Daily B',null,'Québec',null);
 update public.branches set timezone='America/Toronto' where id in(a,b);
 update public.organization_settings set default_payment_method='CASH',receipt_footer='Merci, à bientôt',low_stock_default_threshold=3 where organization_id=org;
 update public.expiry_policies set thresholds_days=array[30,7] where organization_id=org;
 payload:='[{"row_number":2,"raw_data":{"name":"Été, \"Jour\""},"normalized_data":{"name":"Été, \"Jour\"","sku":"DAY-A","barcode":"000DAY01","stock_unit":"tablet"}}]';
 perform public.stage_import_job(job,org,a,'PRODUCTS','jour-produits.csv',payload);
 perform public.stage_import_job(job,org,a,'PRODUCTS','jour-produits.csv',payload);
 perform pg_temp.daily_assert(public.commit_import_job(job)=1,'import posts once');
 perform pg_temp.daily_assert(public.commit_import_job(job)=1,'import exact retry');
 select id into p from public.products where organization_id=org and sku='DAY-A';
 perform pg_temp.daily_assert((select count(*)=1 from public.search_catalog_products(org,'000DAY01','active') where id=p),'barcode resolves one imported product');
 p2:=public.create_catalog_product(org,'{"name":"Sirop du Jour","sku":"DAY-B","barcode":"000DAY02","stock_unit":"bottle"}');
 update public.products set name='Sirop du Jour corrigé' where id=p2;
 payload:=jsonb_build_array(jsonb_build_object('row_number',2,'raw_data',jsonb_build_object('sku','DAY-A'),'normalized_data',jsonb_build_object('sku','DAY-A','stock_unit','tablet','lot_number','DAY-OPEN','expiry_date',(current_date+20)::text,'quantity','20','purchase_cost','1.20','selling_price','2.50','reason','Daily opening')));
 perform public.stage_import_job(stockjob,org,a,'OPENING_STOCK','jour-stock.csv',payload);
 perform pg_temp.daily_assert(public.commit_import_job(stockjob)=1,'opening import');
 perform pg_temp.daily_assert(public.commit_import_job(stockjob)=1,'opening import retry');
 select id into lot from public.batches where branch_id=a and lot_number='DAY-OPEN';
 payload:='[{"row_number":2,"raw_data":{"name":"Fournisseur, Montréal"},"normalized_data":{"name":"Fournisseur, Montréal","code":"DAY-SUP"}}]';
 perform public.stage_import_job(supplierjob,org,a,'SUPPLIERS','jour-fournisseurs.csv',payload);
 perform pg_temp.daily_assert(public.commit_import_job(supplierjob)=1,'supplier import');
 po:=public.create_purchase_order(org,a,(select id from public.suppliers where organization_id=org and code='DAY-SUP'),'DAY-PO',null,null,jsonb_build_array(jsonb_build_object('product_id',p2,'quantity',10,'unit_cost',2)),'day:po');
 perform pg_temp.daily_assert((select status='ordered' from public.purchase_orders where id=po),'submission creates ordered PO');
 select id into pol from public.purchase_order_lines where purchase_order_id=po;
 lines:=jsonb_build_array(jsonb_build_object('purchase_order_line_id',pol,'quantity',4,'unit_cost',3,'selling_price',8,'lot_number','DAY-RECEIVED','expiry_date',current_date+100));
 receipt:=public.receive_purchase_order(po,'DAY-RECEIPT-1',null,lines,null,'day:receipt:1');
 perform pg_temp.daily_assert(public.receive_purchase_order(po,'DAY-RECEIPT-1',null,lines,null,'day:receipt:1')=receipt,'partial receiving retry');
 perform pg_temp.daily_assert((select status='partially_received' from public.purchase_orders where id=po),'partial PO link');
 lines:=jsonb_set(lines,'{0,quantity}','6');
 receipt:=public.receive_purchase_order(po,'DAY-RECEIPT-2',null,lines,null,'day:receipt:2');
 perform pg_temp.daily_assert(public.receive_purchase_order(po,'DAY-RECEIPT-2',null,lines,null,'day:receipt:2')=receipt,'final receiving retry after completion');
 select id into lot2 from public.batches where branch_id=a and lot_number='DAY-RECEIVED';
 perform pg_temp.daily_assert((select on_hand_quantity=10 from public.inventory_balances where batch_id=lot2),'partial plus final stock 4+6=10');
 perform pg_temp.daily_assert((select purchase_cost=3 and selling_price=8 from public.batches where id=lot2),'received actual cost and independent selling price');
 perform pg_temp.daily_assert((select status='received' from public.purchase_orders where id=po),'PO final status');
 perform public.post_inventory_movement(org,a,lot,'ADJUSTMENT_OUT',-1,'day:adjustment','Damaged package','MANUAL_ADJUSTMENT','DAY-ADJ');
 perform public.post_inventory_movement(org,a,lot,'ADJUSTMENT_OUT',-1,'day:adjustment','Damaged package','MANUAL_ADJUSTMENT','DAY-ADJ');
 insert into public.inventory_stock_counts(organization_id,branch_id,notes) values(org,a,'Daily shelf count') returning id into cnt;
 insert into public.inventory_stock_count_lines(stock_count_id,organization_id,branch_id,batch_id,counted_quantity) values(cnt,org,a,lot,18);
 perform public.complete_inventory_stock_count(cnt);
 begin perform public.complete_inventory_stock_count(cnt); raise exception 'second count accepted'; exception when check_violation or no_data_found then null; end;
 perform pg_temp.daily_assert((select on_hand_quantity=18 from public.inventory_balances where batch_id=lot),'20-1 adjustment-1 count=18');
 perform pg_temp.daily_assert((select expected_quantity=19 and counted_quantity=18 from public.inventory_stock_count_lines where stock_count_id=cnt),'persisted count variance');
 perform public.record_expiry_action(lot,'QUARANTINE','Daily inspection');
 perform pg_temp.daily_assert(not exists(select 1 from public.get_fefo_batches(org,a,p) where batch_id=lot),'quarantine removed from sellable allocation');
 perform public.record_expiry_action(lot,'RELEASE_QUARANTINE','Inspection passed');
 perform pg_temp.daily_assert((public.quote_sale(org,a,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)))#>>'{items,0,batch_id}')::uuid=lot,'released eligible lot used by server quote');
 perform public.post_opening_stock(org,a,p,'DAY-RECALL',current_date+5,3,1.2,2.5,'Recall sample','day:recall:opening');
 select id into unsafe from public.batches where branch_id=a and lot_number='DAY-RECALL';
 perform public.record_expiry_action(unsafe,'RECALL','Supplier recall');
 perform pg_temp.daily_assert(not exists(select 1 from public.get_fefo_batches(org,a,p) where batch_id=unsafe),'recall excluded despite earlier expiry');
 quote:=public.quote_sale(org,a,jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1)));
 perform pg_temp.daily_assert((quote#>>'{items,0,batch_id}')::uuid=lot,'server quote skips earlier recalled lot with positive stock');
 perform public.dispose_batch(unsafe,'Recall disposal','day:dispose');
 perform public.dispose_batch(unsafe,'Recall disposal','day:dispose');
 perform pg_temp.daily_assert((select on_hand_quantity=0 from public.inventory_balances where batch_id=unsafe),'disposal consumes three exactly once');
 tr:=public.create_stock_transfer(org,a,b,'DAY-TRANSFER',jsonb_build_array(jsonb_build_object('source_batch_id',lot,'quantity',4)),'day:transfer');
 perform public.approve_stock_transfer(tr);
 perform public.dispatch_stock_transfer(tr); perform public.dispatch_stock_transfer(tr);
 perform public.receive_stock_transfer(tr); perform public.receive_stock_transfer(tr);
 perform pg_temp.daily_assert((select count(*)=2 from public.inventory_movements where reference_type='STOCK_TRANSFER' and reference_id=tr::text),'exactly one source and one destination transfer movement');
 select destination_batch_id into dest_lot from public.stock_transfer_lines where transfer_id=tr;
 perform pg_temp.daily_assert((select on_hand_quantity=14 from public.inventory_balances where batch_id=lot),'transfer source 18-4=14');
 perform pg_temp.daily_assert((select on_hand_quantity=4 from public.inventory_balances where batch_id=dest_lot),'transfer destination 4');
 perform pg_temp.daily_assert((select lot_number='DAY-OPEN' and product_id=p and purchase_cost=1.2 and selling_price=2.5 from public.batches where id=dest_lot),'exact transferred lot unit/cost/price identity');
 canceltr:=public.create_stock_transfer(org,a,b,'DAY-CANCEL',jsonb_build_array(jsonb_build_object('source_batch_id',lot2,'quantity',1)),'day:cancel');
 perform public.cancel_stock_transfer(canceltr,'No longer needed');
 insert into public.customers(organization_id,full_name,phone,preferred_locale) values(org,'Client du Jour','+15555550991','fr') returning id into customer;
 lines:=jsonb_build_array(jsonb_build_object('product_id',p,'quantity',2),jsonb_build_object('product_id',p2,'quantity',2));
 quote:=public.quote_sale(org,a,lines);
 perform pg_temp.daily_assert((quote->>'total_amount')::numeric=21,'quote 2x2.50+2x8=21');
 sale:=public.complete_sale_with_customer(org,a,'DAY-SALE-1',lines,'[{"method":"CASH","amount":21}]','day:sale:1',null,customer,quote,25);
 perform pg_temp.daily_assert(public.complete_sale_with_customer(org,a,'DAY-SALE-1',lines,'[{"method":"CASH","amount":21}]','day:sale:1',null,customer,quote,25)=sale,'sale retry identity');
 perform pg_temp.daily_assert((select amount=21 and tendered_amount=25 and change_amount=4 from public.payments where sale_id=sale),'cash tender/change');
 select id into item from public.sale_items where sale_id=sale and product_id=p2;
 refund:=public.refund_sale(sale,'DAY-REFUND',jsonb_build_array(jsonb_build_object('sale_item_id',item,'quantity',0.5)),'day:refund','Partial non-first item');
 perform pg_temp.daily_assert(public.refund_sale(sale,'DAY-REFUND',jsonb_build_array(jsonb_build_object('sale_item_id',item,'quantity',0.5)),'day:refund','Retry')=refund,'refund retry identity');
 perform pg_temp.daily_assert((select amount=4 from public.sale_refunds where id=refund),'0.5x8 refund=4');
 update public.customers set full_name='Client du Jour modifié',status='archived' where id=customer;
 perform pg_temp.daily_assert((select customer_id=customer from public.sales where id=sale),'history survives edit and archive');
 update public.customers set status='active' where id=customer;
 lines:=jsonb_build_array(jsonb_build_object('product_id',p,'quantity',1));
 quote:=public.quote_sale(org,a,lines);
 sale2:=public.complete_sale_with_customer(org,a,'DAY-SALE-2',lines,'[{"method":"CASH","amount":2.5}]','day:sale:2',null,null,quote,3);
 perform pg_temp.daily_assert((select customer_id is null from public.sales where id=sale2),'customer optional');
 perform pg_temp.daily_assert((select on_hand_quantity=11 from public.inventory_balances where batch_id=lot),'A final 20-1-1-4-2-1=11');
 perform pg_temp.daily_assert((select on_hand_quantity=8.5 from public.inventory_balances where batch_id=lot2),'B final 10-2+0.5=8.5');
 perform pg_temp.daily_assert(not exists(select 1 from public.inventory_balances v where v.branch_id in(a,b) and v.on_hand_quantity<>(select sum(m.quantity_delta) from public.inventory_movements m where m.batch_id=v.batch_id and m.branch_id=v.branch_id)),'all tested balances equal immutable ledger sums');
 perform pg_temp.daily_assert((select count(*)=2 from public.purchase_receipts where purchase_order_id=po),'exactly two receipts');
 perform pg_temp.daily_assert((select count(*)=2 from public.sales where branch_id=a),'exactly two sales');
 perform pg_temp.daily_assert((select count(*)=1 from public.sale_refunds where sale_id=sale),'exactly one refund');
 result:=public.read_operational_report(org,a,'sales',business_day,business_day);
 perform pg_temp.daily_assert((result#>>'{summary,gross}')::numeric=23.5 and (result#>>'{summary,refunds}')::numeric=4 and (result#>>'{summary,net}')::numeric=19.5,'report gross/refund/net');
 perform pg_temp.daily_assert((result#>>'{summary,recorded_payments}')::numeric=23.5 and (result#>>'{summary,payment_difference}')::numeric=0,'payments reconcile to gross');
 perform pg_temp.daily_assert((select sum(total_amount)=23.5 from public.sales where branch_id=a),'independent raw sales total');
 perform pg_temp.daily_assert((select sum(amount)=4 from public.sale_refunds where sale_id=sale),'independent raw refund total');
 perform pg_temp.daily_assert((select sum(amount)=23.5 from public.payments where branch_id=a),'independent raw payments total');
 result:=public.read_operational_report(org,a,'purchasing',business_day,business_day);
 perform pg_temp.daily_assert((result#>>'{summary,ordered_value}')::numeric=20 and (result#>>'{summary,received_value}')::numeric=30 and (result#>>'{summary,outstanding_value}')::numeric=0,'report order estimate20/actual30/outstanding0');
 perform public.refresh_operational_notifications(org);
 select count(*) into before_n from public.notifications where branch_id in(a,b) and resolved_at is null;
 perform public.refresh_operational_notifications(org);
 perform pg_temp.daily_assert((select count(*)=before_n from public.notifications where branch_id in(a,b) and resolved_at is null),'notification refresh no duplicate spam');
 perform pg_temp.daily_assert(exists(select 1 from public.notifications where branch_id=a and type='EXPIRY_ALERT' and resolved_at is null),'real opened stock produces expiry follow-up');
 raise notice 'DAILY TOTALS expected=actual: gross CAD23.50; refund CAD4.00; net CAD19.50; payments CAD23.50; difference0; PO estimate20/received30/outstanding0; A tablet11/B tablet4/source bottle8.5/disposed0';
end $$;
reset role;
select jsonb_build_object('sales',(select sum(total_amount) from public.sales where branch_id='d1111111-1111-4111-8111-111111111111'),'refunds',(select sum(amount) from public.sale_refunds where branch_id='d1111111-1111-4111-8111-111111111111'),'payments',(select sum(amount) from public.payments where branch_id='d1111111-1111-4111-8111-111111111111'),'movements',(select count(*) from public.inventory_movements where branch_id in('d1111111-1111-4111-8111-111111111111','d2222222-2222-4222-8222-222222222222')),'balances',(select jsonb_agg(jsonb_build_object('branch',b.name,'lot',ba.lot_number,'quantity',v.on_hand_quantity)) from public.inventory_balances v join public.batches ba on ba.id=v.batch_id join public.branches b on b.id=v.branch_id where v.branch_id in('d1111111-1111-4111-8111-111111111111','d2222222-2222-4222-8222-222222222222')));
rollback;